def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to fetch the record from common attribute names
        record = getattr(self, 'record', None) or getattr(self, '_record', None)
        if record is None:
            raise AttributeError("Record data not accessible; missing 'record' or '_record' attribute.")
        # Ensure the record behaves like a mapping
        if not hasattr(record, 'keys'):
            raise TypeError(f"Record object of type {type(record).__name__} does not support keys()")
        return list(record.keys())
    except Exception as exc:
        # Propagate exception with context
        raise RuntimeError(f"Failed to retrieve record keys: {exc}") from exc

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError(f"protocol_version must be a tuple (major, minor), got {type(protocol_version).__name__}")

        # Registry of handlers (assumed to be defined on the class).
        registry = getattr(cls, "_protocol_handlers", {})
        if not isinstance(registry, dict):
            registry = {}

        if protocol_version is None:
            # Return a copy containing only defined handlers
            return {ver: h for ver, h in registry.items() if h is not None}
        else:
            handler = registry.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.

    For example, a timeout may be applied::

        from neo4j import unit_of_work

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]

    :param metadata:
        a dictionary with metadata.
        Specified metadata will be attached to the executing transaction and visible in the output of ``dbms.listQueries`` and ``dbms.listTransactions`` procedures.
        It will also get logged to the ``query.log``.
        This functionality makes it easier to tag transactions and is equivalent to ``dbms.setTXMetaData`` procedure, see https://neo4j.com/docs/operations-manual/current/reference/procedures/ for procedure reference.
    :type metadata: dict

    :param timeout:
        the transaction timeout in seconds.
        Transactions that execute longer than the configured timeout will be terminated by the database.
        This functionality allows to limit query/transaction execution time.
        Specified timeout overrides the default timeout configured in the database using ``dbms.transaction.timeout`` setting.
        Value should not represent a negative duration.
        A zero duration will make the transaction execute indefinitely.
        None will use the default timeout configured in the database.
    :type timeout: float or :const:`None`
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # The first positional argument is expected to be a session or a driver.
            if not args:
                raise ValueError("A session or driver must be passed as the first argument.")
            session_or_driver = args[0]
            # Try to start a transaction with metadata and timeout if supported.
            try:
                # The Neo4j driver exposes a `begin_transaction` method that accepts 
                # optional configuration parameters such as metadata and timeout.
                # Not all driver versions may support this, so we use a try/except
                # fallback to a basic transaction creation.
                tx = None
                # Use the `begin_transaction` method if present
                if hasattr(session_or_driver, "begin_transaction"):
                    if metadata is not None and timeout is not None:
                        tx = session_or_driver.begin_transaction(timeout=timeout, metadata=metadata)
                    elif metadata is not None:
                        tx = session_or_driver.begin_transaction(metadata=metadata)
                    elif timeout is not None:
                        tx = session_or_driver.begin_transaction(timeout=timeout)
                    else:
                        tx = session_or_driver.begin_transaction()
                elif hasattr(session_or_driver, "begin_tx"):
                    # older driver API
                    tx = session_or_driver.begin_tx()
                else:
                    # If we cannot start a transaction, fall back to calling the function directly
                    return func(*args, **kwargs)
                # Use a context manager if the transaction object supports it
                try:
                    if hasattr(tx, "__enter__") and hasattr(tx, "__exit__"):
                        with tx as inner_tx:
                            return func(inner_tx, *args[1:], **kwargs)
                    else:
                        # If no context manager support, manually begin/commit/rollback
                        try:
                            result = func(tx, *args[1:], **kwargs)
                            tx.commit()
                            return result
                        except Exception:
                            tx.rollback()
                            raise
                finally:
                    # Ensure the transaction is closed if it implements a close method
                    if hasattr(tx, "close"):
                        tx.close()
            except Exception:
                # In case of any failure to start or use a transaction, fallback to direct call
                return func(*args, **kwargs)
        return wrapper
    return decorator

def index(self, key):
        """ Return the index of the given item.

        :param key: a key
        :return: index
        :rtype: int
        """
        # Prefer a precomputed lookup if available
        if hasattr(self, "index_lookup"):
            try:
                return self.index_lookup[key]
            except KeyError:
                pass

        # Fall back to searching a stored index list
        if hasattr(self, "_index"):
            try:
                return self._index.index(key)
            except ValueError:
                pass

        # If no specific attribute, attempt to infer from data containers
        for attr in ("keys", "key_list", "data_keys"):
            if hasattr(self, attr):
                try:
                    container = getattr(self, attr)
                    return container.index(key)
                except ValueError:
                    pass

        # As a last resort, raise a clear error
        raise KeyError(f"Key {key!r} not found in index.")

def values(self, *keys):
    """Return the values of the record, optionally filtering to include only
    certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Preserve all values when no keys are given
    if not keys:
        try:
            # If the record stores items as a list of (key, value) tuples
            return [value for _, value in self._items]
        except AttributeError:
            # Fallback to dictionary style storage
            return list(self._data.values())

    # Build a list of values according to supplied keys
    values = []
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            try:
                values.append(self._items[key][1])
            except (IndexError, TypeError, AttributeError):
                raise IndexError(f"Index {key} out of range for record items.")
        else:
            # Handle key lookups
            try:
                # First try dictionary storage
                value = self._data[key]
                values.append(value)
            except (KeyError, TypeError, AttributeError):
                # If dictionary lookup fails, try list lookup
                try:
                    values.append(next(val for k, val in self._items if k == key))
                except StopIteration:
                    raise KeyError(f"Key '{key}' not found in record.")
    return values

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # The record is expected to expose a list of field names in ``self._keys`` and a
    # corresponding list of values in ``self._values``. If those attributes are not
    # present, we fall back to a simple dict stored in ``self._dict``.
    if hasattr(self, "_keys") and hasattr(self, "_values"):
        keys_list = list(keys)
        if not keys_list:
            return {k: v for k, v in zip(self._keys, self._values)}
        result = {}
        for k in keys_list:
            if isinstance(k, int):
                if k < 0 or k >= len(self._values):
                    raise IndexError(f"Index {k} out of bounds")
                field = self._keys[k]
                result[field] = self._values[k]
            else:
                if k in self._keys:
                    idx = self._keys.index(k)
                    result[k] = self._values[idx]
                else:
                    result[k] = None
        return result
    elif hasattr(self, "_dict"):
        if not keys:
            return dict(self._dict)
        result = {}
        for k in keys:
            if isinstance(k, int):
                raise IndexError(f"Index {k} out of bounds for dictionary")
            result[k] = self._dict.get(k, None)
        return result
    else:
        raise AttributeError("Record does not expose expected data attributes")

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is None:
        mode = "WRITE"
    else:
        mode = mode.upper()
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is None:
        bookmarks = []
    else:
        try:
            bookmarks = list(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable of bookmark values")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dictionary")

    # Validate hooks
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dict")
    for key, hook in dehydration_hooks.items():
        if not callable(hook):
            raise ValueError(f"dehydration hook for {key!r} is not callable")

    if hydration_hooks is None:
        hydration_hooks = {}
    if not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dict")
    for key, hook in hydration_hooks.items():
        if not callable(hook):
            raise ValueError(f"hydration hook for {key!r} is not callable")

    # Build the BEGIN message payload
    begin_msg = {
        "mode": mode,
        "bookmarks": bookmarks,
        "metadata": metadata or {},
        "timeout": timeout,
        "db": db,
        "imp_user": imp_user,
    }

    # Apply dehydration hooks to the payload before sending
    for key, hook in dehydration_hooks.items():
        if key in begin_msg:
            begin_msg[key] = hook(begin_msg[key])

    # Apply hydration hooks to the payload after sending (if needed)
    # Heuristic: only on metadata portion
    if hydration_hooks and "metadata" in begin_msg:
        for key, hook in hydration_hooks.items():
            if isinstance(begin_msg["metadata"], dict):
                for k, v in list(begin_msg["metadata"].items()):
                    if isinstance(v, key):
                        begin_msg["metadata"][k] = hook(v)

    # Append to the outgoing message queue; assume self._outgoing exists
    try:
        self._outgoing.append(begin_msg)  # pragma: no cover
    except AttributeError:
        # Fallback: if _outgoing not defined, just ignore queueing for demo
        pass

    # Return a Response object; assume a Response class is available in context
    # Pass the message and handlers to the Response constructor
    if 'Response' in globals():
        return Response(begin_msg, **handlers)
    # If Response is not defined, raise a descriptive error
    raise RuntimeError("Response class is not defined in the current context")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Invalid class name: {name!r}")

    if not isinstance(fields, (list, tuple, set)):
        raise TypeError("fields must be an iterable of field names")
    field_names = []
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Invalid field name: {f!r}")
        if f in field_names:
            raise ValueError(f"Duplicate field name: {f!r}")
        field_names.append(f)

    try:
        from shapely.geometry import Point as BasePoint
    except Exception:
        BasePoint = object

    def _init(self, *args, srid=None, **kwargs):
        if len(args) > len(field_names):
            raise TypeError(
                f"Expected at most {len(field_names)} positional args, got {len(args)}"
            )
        for name, value in zip(field_names, args):
            setattr(self, name, value)
        for name, value in kwargs.items():
            if name == "srid":
                continue
            if name not in field_names:
                raise TypeError(f"Unexpected keyword argument: {name!r}")
            setattr(self, name, value)
        for name in field_names:
            if not hasattr(self, name):
                setattr(self, name, None)
        if srid is None and "srid" in kwargs:
            srid = kwargs["srid"]
        if srid is not None:
            try:
                self.srid = srid_map[srid]
            except Exception:
                self.srid = srid
        else:
            self.srid = None

    def _repr(self):
        parts = [f"{name}={getattr(self, name, None)!r}" for name in field_names]
        if hasattr(self, "srid") and self.srid is not None:
            parts.append(f"srid={self.srid!r}")
        return f"{name}({', '.join(parts)})"

    class_dict = {f: None for f in field_names}
    class_dict["_srid_map"] = srid_map
    class_dict["__init__"] = _init
    class_dict["__repr__"] = _repr
    return type(name, (BasePoint,), class_dict)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        if func.__doc__:
            wrapper.__doc__ = f"{func.__doc__}\n\nDeprecated: {message}"
        else:
            wrapper.__doc__ = f"Deprecated: {message}"
        return wrapper
    return decorator

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    import os

    if not isinstance(code, str):
        raise TypeError(f"_inline_r_setup expects a str, got {type(code).__name__}")

    try:
        prefix = "R_OPTION_"
        r_options = []

        for env_key, env_val in os.environ.items():
            if env_key.upper().startswith(prefix):
                option_name = env_key[len(prefix):].lower()
                # Try to interpret the value as a native R literal.
                # Booleans
                lowered = env_val.lower()
                if lowered == "true":
                    r_val = "TRUE"
                elif lowered == "false":
                    r_val = "FALSE"
                else:
                    # Numeric or string
                    try:
                        # If conversion to float succeeds, keep numeric representation
                        float(env_val)
                        r_val = env_val
                    except ValueError:
                        # Escape any double quotes in the string value
                        escaped = env_val.replace('"', r'\"')
                        r_val = f'"{escaped}"'
                r_options.append(f"options({option_name} = {r_val})")

        if r_options:
            header = "\n".join(r_options) + "\n"
            return header + code
        else:
            return code
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to inline R setup: {exc}") from exc

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = OrderedDict()
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a cache key that reflects the function arguments.
            key = args
            if kwargs:
                # Use a sorted tuple of keyword items to keep order deterministic.
                key += tuple(sorted(kwargs.items()))
            if typed:
                # If typed is True, differentiate keys by argument type.
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                value, expire_at = cache[key]
                # If the cached value has expired, discard it.
                if timer() - expire_at > ttl:
                    del cache[key]
                else:
                    # Mark as recently used.
                    cache.move_to_end(key)
                    return value
            except KeyError:
                pass
            # Compute the value and cache it.
            value = func(*args, **kwargs)
            cache[key] = (value, timer())
            # Ensure the cache does not exceed the maximum size.
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return value
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize < 0:
        raise ValueError("maxsize must be non-negative")

    def _key(args, kwargs, typed):
        key = (args, tuple(sorted(kwargs.items())))
        if typed:
            key_types = (
                tuple(type(v) for v in args),
                tuple((k, type(v)) for k, v in sorted(kwargs.items())),
            )
            key = (key, key_types)
        return key

    def decorator(func):
        cache = {}
        usage = []  # list of keys; last element is most recent

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = _key(args, kwargs, typed)
            if k in cache:
                # Move key to the end (most recent)
                try:
                    usage.remove(k)
                except ValueError:
                    pass
                usage.append(k)
                return cache[k]

            r = func(*args, **kwargs)
            cache[k] = r
            usage.append(k)

            if len(cache) > maxsize:
                # Evict the most recently used item
                try:
                    mru_key = usage.pop()
                    del cache[mru_key]
                except IndexError:
                    pass
            return r

        wrapper.cache = cache
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import wraps
    from collections import OrderedDict

    if maxsize is None or maxsize <= 0:
        # Disable caching
        def _decorator(func):
            @wraps(func)
            def _wrapper(*args, **kw):
                return func(*args, **kw)
            return _wrapper
        return _decorator

    def _decorator(user_function):
        cache = OrderedDict()

        def _make_key(args, kwargs):
            if typed:
                key = tuple((type(arg), arg) for arg in args)
                key += tuple((k, (type(v), v)) for k, v in sorted(kwargs.items()))
            else:
                key = args
                key += tuple(sorted(kwargs.items()))
            return key

        @wraps(user_function)
        def _wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                # Move to the end to mark as recently used
                cache.move_to_end(key)
                return cache[key]
            result = user_function(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)  # pop the least recently used item
            return result

        def cache_clear():
            cache.clear()

        def cache_info():
            return {"maxsize": maxsize, "currsize": len(cache)}

        # Expose cache attributes for introspection/debugging
        _wrapper.cache_clear = cache_clear
        _wrapper.cache_info = cache_info

        return _wrapper

    return _decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        if maxsize is not None and not isinstance(maxsize, int):
            raise TypeError("maxsize must be an integer or None")

        cache = {}
        freq = {}

        def make_key(args, kwargs):
            # Build a base key from arguments
            key = args
            if kwargs:
                # sort kwargs items to ensure deterministic order
                key += tuple(sorted(kwargs.items()))
            if typed:
                # include the types of the arguments
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            k = make_key(args, kwargs)
            if k in cache:
                freq[k] += 1
                return cache[k]
            # compute value
            result = func(*args, **kwargs)

            # evict if needed
            if maxsize is not None and maxsize > 0 and len(cache) >= maxsize:
                # find the least frequently used key(s)
                min_freq = min(freq.values())
                # choose one key with that frequency
                for evict_key, f in freq.items():
                    if f == min_freq:
                        cache.pop(evict_key, None)
                        freq.pop(evict_key, None)
                        break

            cache[k] = result
            freq[k] = 1
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = dict.popitem(self, False)
        return key, value
    except KeyError as e:
        raise KeyError("popitem from an empty container") from e
    except Exception as e:
        raise Exception(f"Error executing popitem: {e}") from e

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    # Assume the class has a dictionary-like attribute named `storage`
    storage = getattr(self, "storage", None)
    if storage is None:
        raise AttributeError("The object does not have a 'storage' attribute.")
    if not isinstance(storage, dict):
        raise TypeError("The 'storage' attribute must be a dictionary.")
    try:
        if key not in storage:
            storage[key] = default
        return storage[key]
    except Exception as exc:
        # Attempt to log the exception if a logger is available
        try:
            logger.exception(f"Error in setdefault: {exc}")
        except Exception:
            pass
        raise

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass
                return v
        try:
            wrapper = _update_wrapper(wrapper, method)
        except NameError:
            pass
        return wrapper
    return decorator

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name.strip():
        return False
    try:
        path = os.path.abspath(file_name)
        return os.path.isfile(path)
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to defaults.
    """
    try:
        root = logging.getLogger()
        # Remove and close all handlers
        handlers = root.handlers[:]
        for h in handlers:
            try:
                h.flush()
            except Exception:
                pass
            try:
                h.close()
            except Exception:
                pass
            root.removeHandler(h)
        # Reset root level to WARNING
        root.setLevel(logging.WARNING)
    except Exception as e:
        # Attempt to log the failure, fallback to print if logger not ready
        try:
            logging.getLogger().error("Failed to reset logging: %s", e)
        except Exception:
            print(f"Failed to reset logging: {e}")

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ...     ['x', 'y', 'z'],
    ...     ['q', 'z'],
    ...     [1, 3, 5],
    ...     ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Collect all unique nodes and record first appearance order
    node_order = {}
    for o_idx, ordering in enumerate(orderings):
        for pos, node in enumerate(ordering):
            if node not in node_order:
                node_order[node] = (o_idx, pos)

    # Build graph adjacency and indegree
    adjacency = {node: set() for node in node_order}
    indegree = {node: 0 for node in node_order}

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            src, dst = ordering[i], ordering[i + 1]
            if dst not in adjacency[src]:
                adjacency[src].add(dst)
                indegree[dst] += 1

    # Kahn's algorithm with deterministic ordering based on first appearance
    zero_in = [node for node, deg in indegree.items() if deg == 0]
    zero_in.sort(key=lambda n: node_order[n])
    result = []

    while zero_in:
        node = zero_in.pop(0)
        result.append(node)
        for succ in adjacency[node]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                zero_in.append(succ)
        zero_in.sort(key=lambda n: node_order[n])

    if len(result) != len(node_order):
        raise ValueError("Cycle detected in orderings; cannot merge")
    return result

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    from zope.interface import interfaces

    # Attempt to fetch the attribute that holds the declaration of provided interfaces.
    provides = getattr(object, "__provides__", None)

    if provides is None:
        # If nothing was provided, return an empty declaration.
        return interfaces.Declaration()

    # If it already is a declaration, just return it.
    if interfaces.IDeclaration.providedBy(provides):
        return provides

    # If it looks like a single interface, wrap it in a tuple.
    try:
        iter(provides)
    except TypeError:
        provides = (provides,)

    # Create a new declaration based on whatever was supplied.
    return interfaces.Declaration(provides)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Convert to list to allow multiple passes; validate iterable
    try:
        base_list = list(classes)
    except TypeError as e:
        raise TypeError("classes must be an iterable of class objects") from e

    # Ensure all elements are class types
    for idx, cls in enumerate(base_list):
        if not isinstance(cls, type):
            raise TypeError(f"item at position {idx} ({cls!r}) is not a class")

    seen = set()
    result = []
    for cls in base_list:
        if cls in seen:
            continue  # skip duplicates while preserving order
        redundant = False
        for other in base_list:
            if other is cls:
                continue
            # If cls is a subclass of another, it's redundant
            try:
                if issubclass(cls, other):
                    redundant = True
                    break
            except TypeError:
                # Should not happen because we verified class types
                continue
        if not redundant:
            result.append(cls)
            seen.add(cls)
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names defined on the instance
    attrs = set()
    try:
        instance_attrs = getattr(self, "__dict__", {})
        for key in instance_attrs:
            if not key.startswith("_"):
                attrs.add(key)
    except Exception:
        # If accessing instance __dict__ fails, ignore and continue
        pass

    # Collect attribute names defined on the class that are not callables
    try:
        class_attrs = getattr(self.__class__, "__dict__", {})
        for key, val in class_attrs.items():
            if not key.startswith("_") and not callable(val):
                attrs.add(key)
    except Exception:
        # If accessing class __dict__ fails, ignore and continue
        pass

    # Return the attributes in a deterministic order
    if all:
        return sorted(attrs)
    # If ``all`` is False, filter out callables (methods/functions)
    return sorted([name for name in attrs if not callable(getattr(self, name, None))])

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, "__bases__", ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are needed
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context to an empty dictionary.  Handle missing attribute gracefully.
    try:
        self.context = {}
    except AttributeError:
        self.context = {}

    # Reinitialize bins based on the initialization strategy.
    # Priority: use `initial_value` if it is defined and not None,
    # otherwise fall back to calling `make_bins` (if available).
    try:
        # If bins already exist, preserve their length when resetting.
        if hasattr(self, "bins"):
            bin_len = len(self.bins)
        else:
            bin_len = None

        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Use the predefined initial value for every bin.
            if bin_len is not None:
                self.bins = [self.initial_value] * bin_len
            else:
                self.bins = [self.initial_value]
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            # Delegate bin creation to the user-provided method.
            self.bins = self.make_bins()
    except Exception:
        # If any unexpected issue occurs, silently ignore to keep method robust.
        pass

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        # Attempt to get from a coordinate object's error_indices attribute.
        if hasattr(self, "coords") and isinstance(self.coords, dict):
            coord_obj = self.coords.get(coord_name)
            if coord_obj is not None and hasattr(coord_obj, "error_indices"):
                return list(coord_obj.error_indices)

        # Fallback to a dictionary of error indices stored on the object.
        if hasattr(self, "err_indices") and isinstance(self.err_indices, dict):
            indices = self.err_indices.get(coord_name)
            if indices is not None:
                return list(indices)

        # If no explicit storage for this coordinate, return empty list.
        return []
    except Exception:
        # In case of any unexpected errors, return an empty list to avoid breaking caller logic.
        return []

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure the context and its substructures exist
    if context is None:
        raise ValueError("context must not be None")
    # Ensure context.error exists and is a dict
    if not hasattr(context, "error") or not isinstance(context.error, dict):
        context.error = {}
    # Prepare mapping from error attribute name to coordinate label
    coord_map = {1: "x", 2: "y", 3: "z"}
    # Iterate over all attributes of the graph that represent errors
    for attr_name in dir(self):
        if not attr_name.startswith("error_"):
            continue
        # Attempt to deduce coordinate index based on attribute ordering
        # We treat error attributes as error_<coord>_<suffix>
        parts = attr_name.split("_", 2)
        if len(parts) < 3:
            # Fallback: use first three coordinates sequentially
            try:
                idx = list(self.__dict__.keys()).index(attr_name) + 1
            except Exception:
                idx = 1
        else:
            # The coordinate label is the second part after 'error'
            # e.g., 'error_E_low' → coordinate 'E' (first letter)
            coord_part = parts[1]
            # We map first three allowed letters to x, y, z
            if coord_part.upper() == "X":
                idx = 1
            elif coord_part.upper() == "Y":
                idx = 2
            elif coord_part.upper() == "Z":
                idx = 3
            else:
                # Default to x if unknown
                idx = 1
        coord_label = coord_map.get(idx, "x")
        # Get the suffix after coordinate part
        if len(parts) == 3:
            suffix = parts[2]
        else:
            suffix = None
        # Build the key, e.g., 'x_low'
        if suffix:
            key = f"{coord_label}_{suffix}"
        else:
            key = coord_label
        # Retrieve the indexed value if available
        attr_value = getattr(self, attr_name, None)
        # We assume that if the attribute is a list/tuple/np.ndarray
        # we want the index where the value is True/found. If not,
        # we simply use 0 as placeholder.
        index = None
        try:
            # If the attribute is a numpy array or Pandas Series
            if hasattr(attr_value, "nonzero"):
                index = attr_value.nonzero()[0].tolist()
            elif isinstance(attr_value, (list, tuple)):
                index = [i for i, v in enumerate(attr_value) if v]
            else:
                # Fall back to index 0
                index = [0]
        except Exception:
            index = [0]
        # Append or update the error entry in context.error
        # context.error may store nested dicts; we keep the latest
        context.error[key] = {"index": index}
    # context.value remains unchanged; we intentionally do not modify it here.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.

    This function computes the integral (area under the histogram)
    by multiplying each bin value by the product of the widths of
    the corresponding bin along each axis and summing over all bins.
    """
    # Ensure bins is a numpy array
    import numpy as np
    bins = np.asarray(bins)

    # Standard validation
    if bins.size == 0:
        return 0.0

    # Determine the structure of edges
    # Accept a single 1-D array or a sequence of 1-D arrays
    if isinstance(edges, np.ndarray):
        # Treat as single‑dimensional histogram
        edges_list = [edges]
    else:
        try:
            iter(edges)
            edges_list = list(edges)
        except TypeError:
            # Maybe a single array wrapped in a list/tuple
            edges_list = [edges]

    # If edges are a list of 1‑D arrays, ensure each is 1‑D
    for e in edges_list:
        if not isinstance(e, np.ndarray):
            e = np.asarray(e)
        if e.ndim != 1:
            raise ValueError("Each element of edges must be a 1‑D array of bin edges.")

    # For a 1‑D histogram, edges_list contains one array
    if len(edges_list) == 1:
        width = np.diff(edges_list[0])
        # If bins is 1‑D array, simply multiply
        if bins.ndim == 1:
            return float(np.sum(bins * width))
        # If bins is ND (unlikely for 1‑D edges), compute product of widths
        if bins.ndim > 1:
            # In this unusual case, assuming the same width repeated across all axes
            width_grid = width
            for _ in range(bins.ndim - 1):
                width_grid = np.multiply.outer(width_grid, width)
            return float(np.sum(bins * width_grid))

    # For multi‑dimensional histogram
    # Compute widths for each axis
    widths = [np.diff(e) for e in edges_list]

    # Compute the full grid of widths via successive outer products
    width_grid = widths[0]
    for w in widths[1:]:
        width_grid = np.multiply.outer(width_grid, w)

    # Ensure the width_grid shape matches bins shape
    if width_grid.shape != bins.shape:
        # Attempt broadcasting if shapes differ only by 1 in trailing dimensions
        try:
            width_grid = np.broadcast_to(width_grid, bins.shape)
        except ValueError:
            raise ValueError(
                f"Shape mismatch: bins shape {bins.shape} "
                f"and width grid shape {width_grid.shape} cannot be broadcast."
            )

    integral_value = np.sum(bins * width_grid)
    return float(integral_value)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle single element
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False

    # Avoid treating strings as iterables of characters
    if isinstance(seq, str):
        return False

    # Check common iterable types
    if isinstance(seq, (list, tuple, set, frozenset)):
        has_fill = False
        for item in seq:
            if isinstance(item, Source):
                return False
            if isinstance(item, FillRequest):
                has_fill = True
        return has_fill

    # Generic iterable fallback
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    has_fill = False
    for item in iterator:
        if isinstance(item, Source):
            return False
        if isinstance(item, FillRequest):
            has_fill = True
    return has_fill

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    has_fill = hasattr(obj, "fill") and callable(getattr(obj, "fill", None))
    has_request = hasattr(obj, "request") and callable(getattr(obj, "request", None))
    return has_fill and has_request)

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_method = getattr(obj, "run")
    except Exception:
        return False
    return callable(run_method)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return (hasattr(obj, 'fill') and callable(getattr(obj, 'fill')) and
                hasattr(obj, 'compute') and callable(getattr(obj, 'compute')))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper function that carries a depth counter.
    def _difference(a, b, cur_level):
        # no recursion allowed (cur_level == 0) or infinite recursion mode (cur_level == -1)
        result = {}
        for key, val in a.items():
            if key not in b:
                # key missing in b => include verbatim
                result[key] = val
            else:
                val_b = b[key]
                # Both sides are dicts and we are allowed to recurse
                if isinstance(val, dict) and isinstance(val_b, dict) and (cur_level > 0 or cur_level == -1):
                    # Determine next depth level
                    next_level = cur_level - 1 if cur_level > 0 else -1
                    subdiff = _difference(val, val_b, next_level)
                    if subdiff:
                        result[key] = subdiff
                else:
                    # At this depth we do not recurse into dicts,
                    # so simply compare values for inequality.
                    if val != val_b:
                        result[key] = val
        return result

    # Call the recursive helper with the requested depth
    return _difference(d1, d2, level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    messages = []

    # Example regex for label keys: start with letter/underscore, follow by word chars
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for key, val in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            # For bytes, decode using utf-8 if possible; otherwise skip regex check
            try:
                key_str = key.decode('utf-8') if isinstance(key, bytes) else key
                if not key_pattern.match(key_str):
                    messages.append(
                        {
                            repr(key_str): f"Label key '{key_str}' does not match the regex {key_pattern.pattern}"
                        }
                    )
            except Exception:
                # If decoding fails, consider it invalid
                messages.append({repr(key): 'expected string or bytes-like object'})

        # Validate value(s)
        if isinstance(val, list):
            for item in val:
                if not isinstance(item, (str, bytes)):
                    messages.append({repr(item): 'expected string or bytes-like object'})
                else:
                    # Optional: validate string items against a pattern
                    pass
        else:
            if not isinstance(val, (str, bytes)):
                messages.append({repr(val): 'expected string or bytes-like object'})

    if messages:
        raise ValidationError(messages)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    result = {}
    for key, value in manifest_dict.items():
        try:
            if isinstance(value, dict):
                # Recurse on nested dicts
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                # Assume a helper function that processes lists
                if 'generate_default_observer_schema_list' in globals():
                    result[key] = generate_default_observer_schema_list(value, first_level=False)
                else:
                    # Fallback: replace list with list of Nones
                    result[key] = [None] * len(value)
            else:
                # Non-dict, non-list: replace with None, except for identifying fields
                if first_level and key in ('apiVersion', 'kind'):
                    result[key] = value
                else:
                    result[key] = None
        except Exception as exc:
            # If any unexpected error occurs, default to None
            result[key] = None
    return result

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        # Ensure the path exists and is a directory
        if not os.path.exists(path) or not os.path.isdir(path):
            return False
        # Basic OCFL structure: look for at least one version directory (`v*`)
        entries = os.listdir(path)
        if not entries:
            return False
        has_version_dir = any(
            os.path.isdir(os.path.join(path, e)) and e.startswith('v')
            for e in entries
        )
        return bool(has_version_dir)
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be str, got {type(prefix).__name__}")
    return f"{prefix}{self.status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Attempt to find the log attribute; support common names
        log = getattr(self, '_log', None)
        if log is None:
            log = getattr(self, 'log', None)
        if log is None:
            log = getattr(self, 'validation_log', None)
        if log is None:
            # No log available; return empty string
            return ''

        if not isinstance(prefix, str):
            raise TypeError("prefix must be a string")

        # Build string representation line by line
        lines = []
        for entry in log:
            # If entry is a dict with a 'message' key, use that
            if isinstance(entry, dict) and 'message' in entry:
                msg = entry['message']
            else:
                msg = entry
            # Convert entry to string safely
            try:
                msg_str = str(msg)
            except Exception:
                msg_str = repr(msg)
            lines.append(f"{prefix}{msg_str}")

        return "\n".join(lines)
    except Exception as e:
        # In case of any unexpected error, return a diagnostic string
        return f"<Error generating status string: {e}>"

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ArgumentError(
            'inventory',
            f'Expected a dict, got {type(inventory).__name__}'
        )

    # Determine the specification version to use
    spec_version = getattr(self, 'spec_version', None)
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Coerce the type string to a version if our helper can do so.
            new_ver = getattr(self, '_determine_spec_version', lambda x: None)(type_val)
            if new_ver:
                spec_version = new_ver

    # Iterate over the specification and validate each field
    for field_name, field_spec in getattr(self, 'spec', {}).items():
        if not isinstance(field_spec, dict):
            continue
        expected_type = field_spec.get('type')
        required = field_spec.get('required', False)
        nullable = field_spec.get('nullable', False)

        if field_name not in inventory:
            if required:
                raise ArgumentError(
                    field_name,
                    f'Missing required field `{field_name}`'
                )
            continue

        value = inventory[field_name]

        # Skip further checks for null values if the field is nullable
        if value is None:
            if not nullable:
                raise ArgumentError(
                    field_name,
                    f'Field `{field_name}` is null but not nullable'
                )
            continue

        # Validate based on the expected type
        if isinstance(expected_type, type):
            if not isinstance(value, expected_type):
                raise ArgumentError(
                    field_name,
                    f'Expected type `{expected_type.__name__}`, got `{type(value).__name__}`'
                )
        else:
            # If the spec defines a custom validator, use it
            validate_fn = getattr(expected_type, 'validate', None)
            if validate_fn is not None:
                validate_fn(value, field_name)
            else:
                # Try to coerce / cast; if it fails, raise an error
                try:
                    expected_type(value)
                except Exception:
                    raise ArgumentError(
                        field_name,
                        f'Unable to cast field `{field_name}` to `{expected_type}`'
                    )

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    import re

    def _parse_version(v):
        """Parse a version string into comparable parts."""
        parts = []
        # Split on any sequence of non-digit characters
        for part in re.split(r'\D+', v):
            if part.isdigit():
                parts.append(int(part))
        return parts

    def _compare_versions(v1, v2):
        """Return -1 if v1 < v2, 0 if equal, 1 if v1 > v2."""
        p1 = _parse_version(v1)
        p2 = _parse_version(v2)
        # Compare element-wise
        for a, b in zip(p1, p2):
            if a < b:
                return -1
            if a > b:
                return 1
        # If all matched so far, longer version is greater
        if len(p1) < len(p2):
            return -1
        if len(p1) > len(p2):
            return 1
        return 0

    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping of logical paths")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    result = {}
    for logical_path, version_map in inventory.items():
        if not isinstance(version_map, dict):
            continue  # skip malformed entries
        files_set = set()
        for ver, content_files in version_map.items():
            try:
                comp = _compare_versions(ver, version)
            except Exception:
                # Skip versions that cannot be parsed
                continue
            if comp >= 0:  # ver is same or later than requested
                # Expect content_files to be an iterable of file paths
                if isinstance(content_files, (set, list, tuple)):
                    files_set.update(content_files)
                else:
                    files_set.add(content_files)
        if files_set:
            result[logical_path] = files_set

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError('Fixity must be a dict')
    if 'files' not in fixity:
        raise ValueError('Missing "files" key in fixity block')
    files_block = fixity['files']
    if not isinstance(files_block, dict):
        raise ValueError('"files" entry must be a dict')
    allowed_algos = {'md5', 'sha1', 'sha256', 'sha512'}
    for fname, algo_dict in files_block.items():
        if not isinstance(fname, str):
            raise ValueError('File names in fixity must be strings')
        if fname not in manifest_files:
            raise ValueError(f'File "{fname}" referenced in fixity is not present in the manifest')
        if not isinstance(algo_dict, dict):
            raise ValueError(f'Checksum for file "{fname}" must be a dict')
        if not algo_dict:
            raise ValueError(f'No checksum algorithm provided for file "{fname}"')
        for algo, hash_val in algo_dict.items():
            if algo not in allowed_algos:
                raise ValueError(f'Unsupported checksum algorithm "{algo}" for file "{fname}"')
            if not isinstance(hash_val, str) or not hash_val:
                raise ValueError(f'Invalid checksum value for file "{fname}", algorithm "{algo}"')
    return True  # Success indication if needed.

def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, returns a list containing its absolute path.
    If `path` is a directory, returns a sorted list of absolute file paths
    within that directory and all its subdirectories.

    Raises FileNotFoundError if the path does not exist.
    """
    if not path:
        raise ValueError("path must be a non-empty string")
    if not os.path.exists(path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    result = []
    if os.path.isfile(path):
        result.append(os.path.abspath(path))
    else:
        for root, dirs, files in os.walk(path):
            for f in files:
                result.append(os.path.join(root, f))
        result.sort()
    return result

def _group_files_by_xml_filename(source, xmls, files):
    """Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory or zip file (unused in this implementation but kept for API compatibility).
    xmls : list
        List of XML file paths.
    files : list
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        key: basename of the XML files (without extension)
        value: list of files that share that basename, including the XML file itself
    """
    import os

    if not isinstance(xmls, list) or not isinstance(files, list):
        raise TypeError("Both 'xmls' and 'files' must be lists")

    # Map basename (without extension) to a list of related files
    grouped = {}
    for xml_path in xmls:
        try:
            base = os.path.splitext(os.path.basename(xml_path))[0]
        except Exception as exc:
            # Skip invalid entries silently
            continue
        grouped.setdefault(base, []).append(xml_path)

    # Associate each non‑XML file that matches a basename
    for file_path in files:
        try:
            base = os.path.splitext(os.path.basename(file_path))[0]
        except Exception:
            continue
        if base in grouped:
            grouped[base].append(file_path)

    # Ensure each group has unique entries and maintain order
    cleaned = {}
    for base, file_list in grouped.items():
        seen = set()
        uniq = []
        for f in file_list:
            if f not in seen:
                uniq.append(f)
                seen.add(f)
        if uniq:
            cleaned[base] = uniq

    return cleaned

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    def _element_to_dict(element):
        """Recursively convert an ET.Element into a Python dict."""
        d = {element.tag: {} if element.attrib or list(element) else element.text}
        # Add attributes
        if element.attrib:
            d[element.tag].update({f"@{k}": v for k, v in element.attrib.items()})
        # Add children
        for child in list(element):
            child_dict = _element_to_dict(child)
            child_key = child.tag
            # Handle multiple children with same tag
            if child_key in d[element.tag]:
                if not isinstance(d[element.tag][child_key], list):
                    d[element.tag][child_key] = [d[element.tag][child_key]]
                d[element.tag][child_key].append(child_dict[child_key])
            else:
                d[element.tag].update(child_dict)
        return d

    data_dict = {}
    try:
        for fname in os.listdir(folder):
            if not fname.lower().endswith('.xml'):
                continue
            file_path = os.path.join(folder, fname)
            if not os.path.isfile(file_path):
                continue
            try:
                tree = ET.parse(file_path)
                root = tree.getroot()
                parsed = _element_to_dict(root)
                base_name = os.path.splitext(fname)[0]
                data_dict[base_name] = parsed
            except Exception:
                # Skip files that cannot be parsed as XML
                continue
    except Exception:
        # Folder may not exist or be inaccessible
        return {}
    return data_dict

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
            if results:
                if isinstance(results[0], str):
                    return results[0]
                else:
                    return results[0].text_content() if hasattr(results[0], 'text_content') else str(results[0])
        except Exception:
            continue
    return None

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    def decorator(func):
        # Try to use a preferred registration method if it exists
        try:
            if hasattr(self, "register_listener"):
                self.register_listener(hook, func)
            elif hasattr(self, "_registry"):
                # Expect _registry to be a dict mapping hooks to lists of callables
                listeners = getattr(self, "_registry").setdefault(hook, [])
                listeners.append(func)
            else:
                raise AttributeError(
                    "No suitable registration method or _registry found on the instance."
                )
        except Exception as exc:
            raise RuntimeError(
                f"Failed to register listener for hook {hook!r}: {exc}"
            ) from exc
        return func
    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    try:
        if not isinstance(user, str) or not user.strip():
            raise ValueError("user must be a non-empty string")
        if not isinstance(etcd_host, str) or not etcd_host.strip():
            raise ValueError("etcd_host must be a non-empty string")
        if not isinstance(etcd_port, int):
            raise ValueError("etcd_port must be an integer")
        if not (1 <= etcd_port <= 65535):
            raise ValueError("etcd_port must be between 1 and 65535")
    except Exception as exc:
        raise ValueError(f"Invalid configuration parameter: {exc}") from exc

    config = {
        "user": user.strip(),
        "etcd_host": etcd_host.strip(),
        "etcd_port": etcd_port,
    }
    return config

def _fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # The input must be timezone‑aware
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # 1. Ensure we are working with a UTC datetime
    try:
        utc_dt = dt.astimezone(datetime.timezone.utc)
    except Exception:
        # If the tzinfo provides an offset we can convert manually
        off = dt.tzinfo.utcoffset(dt)
        if off is None:
            raise ValueError("dt must have a UTC offset")
        utc_dt = dt - off

    # 2. Convert the UTC datetime to the target timezone (self)
    try:
        new_dt = utc_dt.astimezone(self)
    except Exception:
        # Fallback: use tkinter replace
        new_dt = dx = utc_dt.replace(tzinfo=self)

    # 3. Detect whether the new datetime occurs in an ambiguous period.
    # An ambiguous period arises when the offset differs before and after.
    ambiguous = False
    try:
        offset_now = self.utcoffset(new_dt)
        offset_next = self.utcoffset(new_dt + datetime.timedelta(hours=1))
        if offset_now != offset_next:
            ambiguous = True
    except Exception:
        ambiguous = False

    # 4. Decide on the fold flag.  If the user supplied a fold flag,
    #     honour it; otherwise default to 0 for the “first” occurrence.
    fold = getattr(dt, "fold", 0)
    if ambiguous and fold == 0:
        # If the offset after 30 minutes matches the current offset,
        # we are on the second (fold=1) occurrence.
        try:
            after_half = self.utcoffset(new_dt + datetime.timedelta(minutes=30))
            if after_half == offset_now:
                fold = 1
        except Exception:
            pass

    # 5. Return the datetime with the fold adjusted if supported.
    try:
        return new_dt.replace(fold=fold)
    except Exception:
        return new_dt

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    pkg_name = __package__ or __name__
    # Try importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version
        return version(pkg_name)
    except Exception:
        # Fallback to pkg_resources for older Python versions
        try:
            import pkg_resources
            return pkg_resources.get_distribution(pkg_name).version
        except Exception:
            return default}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Extract pieces as strings
    try:
        if isinstance(pieces, dict):
            major = str(pieces.get('major', ''))
            minor = str(pieces.get('minor', ''))
            patch = str(pieces.get('patch', ''))
            prerelease = str(pieces.get('prerelease', ''))
            metadata = str(pieces.get('metadata', ''))
        elif isinstance(pieces, (list, tuple)):
            if len(pieces) != 5:
                raise ValueError("pieces tuple/list must contain 5 elements")
            major, minor, patch, prerelease, metadata = map(str, pieces)
        else:
            raise TypeError("pieces must be a dict or a 5-element list/tuple")
    except Exception as exc:
        raise ValueError(f"Invalid pieces format: {exc}") from exc

    # Build the version string based on the requested style
    if style == 'full':
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if metadata:
            base += f"+{metadata}"
        return base
    elif style == 'short':
        return f"{major}.{minor}"
    elif style == 'raw':
        # Concatenate all parts without separators
        return ''.join(part for part in (major, minor, patch, prerelease, metadata) if part)
    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: 'full', 'short', 'raw'.")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # If the input is not iterable, treat as having no plus
        if any(p == '+' for p in pieces):
            return '.'
        return '+'
    except Exception:
        # On any runtime error (e.g., pieces not iterable), default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate and build the full command list
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if isinstance(args, (list, tuple)):
        cmd_list.extend(args)
    elif isinstance(args, str):
        cmd_list.append(args)
    elif args is not None:
        raise TypeError("args must be None, a string, or a list/tuple of strings")

    # Merge environment variables
    final_env = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict if provided")
        final_env.update(env)

    # Execute the command
    try:
        if verbose:
            print(f"Running command: {' '.join(cmd_list)}")

        res = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=final_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True,
            check=True
        )

        if verbose:
            print("Command succeeded with output:")
            print(res.stdout)
        return res.stdout

    except subprocess.CalledProcessError as e:
        stderr_output = e.stderr if not hide_stderr else ""
        msg = (
            f"Command {' '.join(cmd_list)} failed with return code {e.returncode}\n"
            f"Stdout:\n{e.stdout}\n"
            f"Stderr:\n{stderr_output}"
        )
        raise RuntimeError(msg) from e
    except Exception as exc:
        # Catch all other unexpected errors and raise a runtime error
        raise RuntimeError(f"Unexpected error when running command {' '.join(cmd_list)}: {exc}") from exc

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not isinstance(method, str):
        raise TypeError("method must be a string")

    def decorate(f):
        if not callable(f):
            raise TypeError("handler must be callable")
        try:
            HANDLERS.setdefault(vcs, {})[method] = f
        except Exception as e:
            raise RuntimeError(f"Failed to register handler: {e}") from e
        return f

    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import hashlib, pickle

    def _compute_digest(obj):
        try:
            data = pickle.dumps(obj, protocol=pickle.HIGHEST_PROTOCOL)
        except Exception:
            return None
        return hashlib.sha256(data).hexdigest()

    def _iterate(obj):
        """Yield all objects recursively."""
        if obj is None:
            return
        # If obj is a container, iterate through its contents
        if isinstance(obj, dict):
            for val in obj.values():
                yield from _iterate(val)
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                yield from _iterate(item)
        elif hasattr(obj, "children") and isinstance(obj.children, (list, tuple, set)):
            for child in obj.children:
                yield from _iterate(child)
        else:
            # Treat scalars and objects with no children as leaf nodes
            yield obj

    num_objects = 0
    good_objects = 0

    # Ensure we have a root object to traverse
    if hasattr(self, "root"):
        root_obj = self.root
    else:
        raise AttributeError("The instance must have a 'root' attribute representing the hierarchy root.")

    for obj in _iterate(root_obj):
        num_objects += 1
        valid = True
        error_messages = []

        # Validate object if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    validation_result = obj.validate()
                    if validation_result is False:
                        valid = False
                        error_messages.append("validate() returned False")
                    elif isinstance(validation_result, Exception):
                        valid = False
                        error_messages.append(str(validation_result))
                elif hasattr(obj, "validate") and not callable(obj.validate):
                    # If validate is a boolean attribute
                    if not bool(obj.validate):
                        valid = False
                        error_messages.append("validate attribute is False")
                # If no validate method/attribute, assume valid
            except Exception as e:
                valid = False
                error_messages.append(f"validation raised exception: {e}")

        # Check digests if requested
        if check_digests and hasattr(obj, "digest"):
            try:
                expected = getattr(obj, "digest")
                computed = _compute_digest(obj)
                if computed is None or expected != computed:
                    valid = False
                    error_messages.append(f"Digest mismatch (expected {expected}, got {computed})")
            except Exception as e:
                valid = False
                error_messages.append(f"Digest check raised exception: {e}")

        if valid:
            good_objects += 1
        else:
            if show_warnings:
                obj_repr = repr(obj)
                for msg in error_messages:
                    print(f"[WARNING] Object {obj_repr} failed validation: {msg}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Ensure input is a non-empty string consisting of digits
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        return ""

    try:
        # Convert to integer and increment
        new_value = int(version) + 1
    except (ValueError, TypeError):
        return ""

    # Convert back to string with appropriate zero padding
    new_str = str(new_value)
    if len(new_str) < len(version):
        new_str = new_str.zfill(len(version))
    return new_str

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Make a shallow copy to avoid modifying the caller's dict directly
    amended = dict(params)
    if bug_ids:
        if not hasattr(bug_ids, "__iter__"):
            raise TypeError("bug_ids must be iterable")
        # Convert each id to string, filtering out None or empty values
        cleaned_ids = [str(bid) for bid in bug_ids if bid is not None]
        if cleaned_ids:
            # Bugzilla expects comma-separated list for 'id' or 'ids' parameter
            # Use 'ids' as the standard key for multiple IDs
            amended["ids"] = ",".join(cleaned_ids)
    return amended

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    import argparse
    import sys

    # Flatten arguments if a single iterable is passed
    if arguments and len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        args_to_parse = list(arguments[0])
    else:
        args_to_parse = list(arguments)

    parser = argparse.ArgumentParser(
        description="Process command line arguments."
    )

    # Example arguments – users can modify as needed
    parser.add_argument(
        "input",
        nargs="?",
        help="Path to the input file."
    )
    parser.add_argument(
        "-o",
        "--output",
        help="Path to the output file."
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="store_true",
        help="Enable verbose mode."
    )
    parser.add_argument(
        "-V",
        "--version",
        action="version",
        version="%(prog)s 1.0"
    )

    try:
        if args_to_parse:
            return parser.parse_args(args_to_parse)
        else:
            return parser.parse_args()
    except Exception as exc:
        # Raise a clear error message while preserving the original exception context
        raise ValueError(f"Argument parsing failed: {exc}") from exc

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string.
    """
    try:
        if not hasattr(parser, "_actions"):
            raise TypeError("The provided object does not appear to be an argparse.ArgumentParser instance.")
        # Preserve the original order of appearance
        ordered_flags = []
        seen = set()
        for action in parser._actions:
            for flag in getattr(action, "option_strings", []):
                if flag not in seen:
                    ordered_flags.append(flag)
                    seen.add(flag)
        return " ".join(ordered_flags)
    except Exception as exc:
        raise ValueError(f"Failed to extract flags from parser: {exc}") from exc

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    def is_mapping_node(node):
        return hasattr(node, "tag") and node.tag == "tag:yaml.org,2002:map" and hasattr(node, "value")

    merged = {}
    order = []

    for key, value in nodes:
        key_str = key.value
        if key_str in merged:
            existing_key, existing_value = merged[key_str]
            if is_mapping_node(existing_value) and is_mapping_node(value):
                # Recursively deep merge the mapping nodes
                merged_value_list = deep_merge_nodes(existing_value.value + value.value)
                merged_value = existing_value.__class__(tag=existing_value.tag, value=merged_value_list)
                merged[key_str] = (existing_key, merged_value)
            else:
                # Non-mapping values: the last one wins
                merged[key_str] = (existing_key, value)
        else:
            merged[key_str] = (key, value)
            order.append(key_str)

    # Return the merged list in the order of first appearance of each key
    return [(merged[k][0], merged[k][1]) for k in order]

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    # Basic validation
    if parser is None:
        raise ValueError("parser argument cannot be None")

    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance (missing '_actions' attribute)")

    flags = []
    for action in actions:
        # Skip actions that do not have option strings (e.g., positional arguments)
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("response must not be None")
    try:
        # Ensure we can index the response (convert to list if needed)
        data = list(response)
    except TypeError as exc:
        raise TypeError("response must be an iterable") from exc

    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _pager():
        """Yield slices of the data list of size max_results."""
        total = len(data)
        for start in range(0, total, max_results):
            # Yield a slice up to max_results
            yield data[start:start + max_results]

    return _pager()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected a dict, got {type(d).__name__}")
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Basic checks: if url is falsy, return as is
    if not url:
        return ''

    # url_args should be a mapping; if not provided, nothing to replace
    if not url_args:
        return url

    try:
        # Use regex to match {key} or <key> placeholders
        pattern = re.compile(r'\{(\w+)\}|\<(\w+)\>')

        def _replacer(match):
            # Extract key from either group 1 or group 2
            key = match.group(1) or match.group(2)
            if key in url_args:
                # Safely convert value to string
                return str(url_args[key])
            # If key not found, keep the original placeholder
            return match.group(0)

        return pattern.sub(_replacer, url)
    except Exception as exc:
        # In case of any unexpected error, log a warning and return original URL
        logger.warning(f'_replace_url_args encountered an error: {exc!s}')
        return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # If the value is actually None, treat it as representing None.
    if val is None:
        return True
    # Check string representations that typically signify None.
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string or whitespace-only strings represent None.
        if not stripped:
            return True
        # Case-insensitive match for common None-like tokens.
        if stripped.lower() in ('none', 'null'):
            return True
    # For any other type or non-matching string, it does not represent None.
    return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    # Basic validation: ensure the object has the attributes argparse uses
    if parser is None or not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in parser._actions:
        # Skip actions that don't have option strings (e.g. positional arguments)
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)

    # Return a single string with flags separated by spaces
    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if number < 0:
        raise ValueError("number must be non-negative")

    # Ensure alphabet is a sequence of unique symbols and has at least two characters
    if not hasattr(alphabet, "__iter__"):
        raise TypeError("alphabet must be a sequence")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet symbols must be unique")

    # Validate padding, if provided
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer")

    # Convert number to base representation using the alphabet
    digits: List[str] = []
    n = number
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding with the zero symbol if requested
    if padding is not None and len(digits) < padding:
        zeros = [alphabet[0]] * (padding - len(digits))
        digits = zeros + digits

    return "".join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type checks
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dict")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    def _recursive_replace(data):
        """Recursively replace the specified key with the register number."""
        if isinstance(data, dict):
            # Capture keys to modify to avoid RuntimeError during iteration
            keys_to_modify = [k for k in data if k == register_value]
            for old_key in keys_to_modify:
                # Move the value to the new key, preserving type validity
                data[register_number] = data.pop(old_key)

            # Recurse into nested dictionaries
            for value in data.values():
                _recursive_replace(value)
        elif isinstance(data, (list, tuple)):
            for item in data:
                _recursive_replace(item)
        # Other types are ignored

    _recursive_replace(flow_params)
    return flow_params

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f'subclasses() expects a class, got {type(cls).__name__}')
    seen = set()
    queue = list(cls.__subclasses__())
    while queue:
        sub = queue.pop()
        if sub not in seen:
            seen.add(sub)
            # Extend the queue with the subclasses of the current subclass
            try:
                queue.extend(sub.__subclasses__())
            except TypeError:
                # In case sub.__subclasses__() fails, skip this subclass
                continue
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols.")
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet contains duplicate characters.")
    char_to_value = {c: i for i, c in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in the alphabet.")
        result = result * base + char_to_value[ch]
    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import os
    import tarfile
    import tempfile
    import requests

    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Unable to download archive from {url}") from exc

    if destination_path.exists() and not destination_path.is_dir():
        raise OSError(f"Destination {destination_path} exists and is not a directory")

    if not destination_path.exists():
        try:
            os.makedirs(destination_path, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Could not create destination directory {destination_path}") from exc

    fd, temp_path = tempfile.mkstemp(suffix=".tar.gz")
    try:
        with os.fdopen(fd, "wb") as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
    except Exception as exc:
        try:
            os.remove(temp_path)
        except Exception:
            pass
        raise RuntimeError("Failed to write the downloaded archive to a temporary file") from exc

    try:
        with tarfile.open(temp_path, "r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except Exception as exc:
        raise RuntimeError("Failed to extract the archive") from exc
    finally:
        try:
            os.remove(temp_path)
        except Exception:
            pass

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() is not available on all platforms; fall back to platform module
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        if len(name) <= 1:
            return name
        # Match strings that start and end with the same quote character
        match = re.match(r"^(['\"<])(?P<content>.*)\1$", name)
        if match:
            content = match.group('content')
            # Unescape any escaped quotes or backslashes within the string
            content = content.replace(r'\"', '"').replace(r"\'", "'").replace(r'\\', '\\')
            return content
        return name
    except Exception:
        return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re, sys, os

    if not isinstance(s, (str, bytes)):
        raise TypeError(f"Input must be a string or bytes, got {type(s)!r}")

    # Decode bytes to str if necessary
    if isinstance(s, bytes):
        s = s.decode('utf-8')

    # Determine which platform to use
    if platform == 'this':
        platform_flag = 0 if os.name == 'nt' else 1
    elif platform in (0, 1):
        platform_flag = platform
    else:
        raise ValueError(f"Invalid platform specifier: {platform!r}")

    # Patterns for POSIX and Windows
    posix_pat = re.compile(
        r'''(?:"(?P<sq>[^"]*)"|'(?P<dq>[^']*)'|(?P<plain>[^ \t\n\r]+))''',
        re.UNICODE)
    win_pat = re.compile(
        r'''(?:"(?P<sq>[^"]*)"|(?P<plain>[^ \t\n\r"^]+))''',
        re.UNICODE)

    pattern = posix_pat if platform_flag == 1 else win_pat

    result = []
    pos = 0
    for m in pattern.finditer(s):
        if m.index != pos:
            # there was unmatched text between tokens
            raise ValueError(f"Could not parse input at position {pos}: '{s[pos:m.index]}'")
        pos = m.end()
        if m.group('sq') is not None:
            result.append(m.group('sq'))
        elif m.group('dq') is not None:
            result.append(m.group('dq'))
        else:
            result.append(m.group('plain'))

    if pos != len(s):
        # dangling characters that were not matched
        raise ValueError(f"Could not parse input at end: '{s[pos:]}'")

    return result**

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        addrinfos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be the local host
        return False
    except Exception:
        # Catch any other unexpected exceptions and conservatively return False
        return False

    for res in addrinfos:
        family, _, _, _, sockaddr = res
        addr = sockaddr[0]
        if family == socket.AF_INET:
            if addr == "127.0.0.1":
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address
            if addr == "::1" or addr == "::1%lo0":
                return True
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything."""
    target_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite is not allowed
    if not overwrite and os.path.isfile(target_path):
        return

    # Ensure parent directories exist
    parent_dir = os.path.dirname(target_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError:
            if not os.path.isdir(parent_dir):
                raise

    # Write the rendered configuration atomically
    temp_path = target_path + ".tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(temp_path, mode)
        os.replace(temp_path, target_path)
    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass

    return target_path

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
