    except ValueError:
        return False

def find_roots(
    graph: "Graph",
    prop: "URIRef",
    roots: Optional[Set["Node"]] = None,
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if graph is None:
        raise ValueError("graph must not be None")

    child_to_parents: dict["Node", Set["Node"]] = {}
    all_nodes: Set["Node"] = set()

    try:
        for child, _ , parent in graph.triples((None, prop, None)):
            if child not in child_to_parents:
                child_to_parents[child] = set()
            child_to_parents[child].add(parent)
            all_nodes.add(child)
            all_nodes.add(parent)
    except Exception as e:
        raise RuntimeError(f"Failed to iterate graph triples for prop {prop}: {e}") from e

    # Nodes that never appear as a child are roots
    computed_roots = all_nodes - set(child_to_parents.keys())

    if roots is None:
        custom_roots = set()
    else:
        custom_roots = set(roots)

    return computed_roots | custom_roots

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        Shape of the array to create.
    dtype : numpy.dtype
        Data-type of the array to create.

    Returns
    -------
    numpy.ndarray
        An uninitialized array of the given shape and dtype.
    """
    # Validate shape input
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    try:
        shape = tuple(int(dim) for dim in shape)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"All dimensions in shape must be integers: {exc}") from exc
    for dim in shape:
        if dim < 0:
            raise ValueError("All dimensions in shape must be non-negative integers")

    # Ensure dtype is a np.dtype instance
    try:
        dtype = np.dtype(dtype)
    except TypeError as exc:
        raise ValueError(f"Invalid dtype specified: {exc}") from exc

    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape} and dtype {dtype}: {exc}") from exc

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be array-like or numeric") from e
    mean = 0.2
    sigma = 0.1
    if sigma <= 0:
        raise ValueError("Sigma must be positive")
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coeff * np.exp(-((arr - mean) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    configs = {}
    error_records = []
    logger = logging.getLogger('config_loader')

    # Lazy imports of configuration parsers
    try:
        import yaml
    except Exception:
        yaml = None
    try:
        import toml
    except Exception:
        toml = None
    try:
        import json
    except Exception:
        json = None

    def _resolve_env_in_value(val):
        if isinstance(val, str):
            return os.path.expandvars(val)
        return val

    def _recursive_env_resolve(obj):
        if isinstance(obj, dict):
            return {k: _recursive_env_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_recursive_env_resolve(elem) for elem in obj]
        else:
            return _resolve_env_in_value(obj)

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                raw = fd.read()
        except Exception as e:
            rec = logger.makeRecord(
                'config_loader',
                logging.ERROR,
                fname,
                0,
                f'Cannot read configuration file {fname}: {e}',
                args=None,
                exc_info=(type(e), e, e.__traceback__),
            )
            error_records.append(rec)
            continue

        parsed = None
        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext in ('.yaml', '.yml') and yaml:
                parsed = yaml.safe_load(raw)
            elif ext == '.toml' and toml:
                parsed = toml.loads(raw)
            elif ext == '.json' and json:
                parsed = json.loads(raw)
            else:
                # Try yaml if available, else toml
                if yaml:
                    parsed = yaml.safe_load(raw)
                elif toml:
                    parsed = toml.loads(raw)
                else:
                    raise ValueError('No suitable parser available')
        except Exception as e:
            rec = logger.makeRecord(
                'config_loader',
                logging.ERROR,
                fname,
                0,
                f'Error parsing configuration file {fname}: {e}',
                args=None,
                exc_info=(type(e), e, e.__traceback__),
            )
            error_records.append(rec)
            continue

        if parsed is None:
            parsed = {}

        if resolve_env:
            try:
                parsed = _recursive_env_resolve(parsed)
            except Exception as e:
                rec = logger.makeRecord(
                    'config_loader',
                    logging.ERROR,
                    fname,
                    0,
                    f'Error resolving environment variables in {fname}: {e}',
                    args=None,
                    exc_info=(type(e), e, e.__traceback__),
                )
                error_records.append(rec)

        if overrides and isinstance(overrides, dict):
            try:
                parsed.update(overrides)
            except Exception as e:
                rec = logger.makeRecord(
                    'config_loader',
                    logging.ERROR,
                    fname,
                    0,
                    f'Error applying overrides to {fname}: {e}',
                    args=None,
                    exc_info=(type(e), e, e.__traceback__),
                )
                error_records.append(rec)

        configs[fname] = parsed

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Failed to encode string to UTF-8: {exc}") from exc
    return obj

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple (major, minor) or None")

    # Attempt to get a pre‑registered mapping, if one exists
    handlers = getattr(cls, "_protocol_handlers", None)

    if not handlers:
        # Build the mapping by inspecting class attributes that look
        # like protocol handler subclasses.  A handler is considered to
        # define a protocol version if it has a `_protocol_version`
        # attribute of the form (major, minor).  Other attributes or
        # values are ignored.
        handlers = {}
        for name, value in cls.__dict__.items():
            if isinstance(value, type) and hasattr(value, "_protocol_version"):
                ver = value._protocol_version
                # Only use the handler if the version is a valid tuple.
                if isinstance(ver, tuple) and len(ver) == 2:
                    handlers[ver] = value

    # Return the desired subset of the mapping
    if protocol_version is None:
        return handlers.copy()
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def from_raw_values(cls, values):
        """
        Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values must not be None")
        bookmarks = []
        for val in values:
            if not isinstance(val, str):
                raise TypeError(f"Bookmark value must be a string, got {type(val).__name__}")
            try:
                # Assuming each raw string can be converted to a Bookmark instance
                bookmark = Bookmark.from_raw(val)
            except Exception as exc:
                raise ValueError(f"Failed to parse bookmark '{val}': {exc}") from exc
            bookmarks.append(bookmark)
        return cls(bookmarks=bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a list or tuple (sequence types), return as is
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))

    # If seq is a string or bytes, treat it as a string type
    if isinstance(seq, (str, bytes, bytearray)):
        return (seq, type(seq))

    # If seq is an iterable but not string/bytes, convert to a list
    # We allow optional bufsize to limit processing for generators
    try:
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes, bytearray)):
            if bufsize is not None:
                # lazily read up to bufsize elements if seq is a generator/iterator
                from itertools import islice
                seq_list = list(islice(seq, bufsize))
                # If seq had more items beyond bufsize, keep a reference to the iterator
                # to allow further consumption if needed
                remaining_iter = None
                try:
                    remaining_iter = seq  # assume seq supports __next__
                except Exception:
                    remaining_iter = None
                if remaining_iter is not None:
                    # Attach remaining iterator to list via attribute for later retrieval
                    seq_list._remaining_iter = remaining_iter
                return (seq_list, type(seq))
            else:
                return (list(seq), type(seq))
    except Exception:
        # If any error occurs, just treat seq as a single-element sequence
        return ([seq], type(seq))

    # Fallback: treat seq as a single element sequence
    return ([seq], type(seq))

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    Parameters
    ----------
    hist : histogram-like object
        The histogram to convert.  It must expose an iterable of
        bin objects that have the attributes `left` and `right`, and
        a value attribute that can be accessed as `value`, `content`,
        or simply the bin object itself if it is numeric.
    make_value : callable, optional
        Function that transforms a bin into the value part of a graph
        point.  If not provided, the bin's value is used.
    get_coordinate : {"left", "right", "middle"}, str
        Specifies which coordinate of the bin will be used as the `x`
        value of the graph point.
    field_names : tuple, optional
        Names of the fields returned in the graph points.  The first
        entry must correspond to the coordinate, the remaining entries
        correspond to the unpacked result of `make_value`.  The length
        of `field_names` must equal the number of values produced.
    scale : any, optional
        If `True`, the histogram's own scale will be used.  Otherwise
        the value is passed through unchanged.  If not supplied,
        ``None`` is used.

    Returns
    -------
    dict
        A simple representation of a graph.  The return value is a
        dictionary with two keys:
        - ``points``: a list of dictionaries mapping field names to
          values.
        - ``scale``: the scale passed through or taken from the
          histogram.

    Notes
    -----
    This implementation is intentionally lightweight and does not rely
    on any particular histogram or graph library.  It expects the
    histogram to expose iterable bins with the necessary attributes; if
    the interface differs, a small wrapper may be needed.
    """
    # Helper to fetch the coordinate from a bin
    def _get_coord(bin_obj):
        try:
            if get_coordinate == "left":
                return getattr(bin_obj, "left")
            if get_coordinate == "right":
                return getattr(bin_obj, "right")
            if get_coordinate == "middle":
                left = getattr(bin_obj, "left")
                right = getattr(bin_obj, "right")
                return (left + right) / 2.0
        except AttributeError:
            pass
        # Fallback: guess that bin is a tuple (left, right, value) or (left, right)
        if isinstance(bin_obj, (list, tuple)):
            if get_coordinate == "left":
                return bin_obj[0]
            if get_coordinate == "right":
                return bin_obj[1]
            if get_coordinate == "middle":
                return (bin_obj[0] + bin_obj[1]) / 2.0
        raise ValueError("Unable to determine coordinate from bin")

    # Prepare the list of point dictionaries
    points = []

    # Determine the collection of bins.  Try common attributes, then fallback to iteration.
    try:
        bins = getattr(hist, "bins", None) or getattr(hist, "_bins", None)
        if bins is None:
            bins = hist  # assume hist itself is iterable
    except Exception:
        bins = hist

    # Resolve the scale
    if scale is True:
        try:
            scale = getattr(hist, "scale", None)
        except Exception:
            scale = None

    for bin_obj in bins:
        # Get the coordinate
        try:
            x = _get_coord(bin_obj)
        except Exception as exc:
            raise ValueError(f"Could not extract coordinate from bin {bin_obj}") from exc

        # Determine the value component(s)
        if make_value is not None:
            try:
                val = make_value(bin_obj)
            except Exception as exc:
                raise ValueError(f"make_value failed for bin {bin_obj}") from exc
        else:
            # Try common value attributes
            for attr in ("value", "content", "y", "data"):
                if hasattr(bin_obj, attr):
                    val = getattr(bin_obj, attr)
                    break
            else:
                # Assume bin itself is numerical
                val = bin_obj

        # Build the point mapping
        point = {field_names[0]: x}

        # If val is a tuple/list, unpack into remaining field names
        if isinstance(val, (tuple, list)):
            if len(field_names) - 1 != len(val):
                raise ValueError(f"Inconsistent number of fields: expected {len(field_names)-1}, got {len(val)}")
            for name, value in zip(field_names[1:], val):
                point[name] = value
        else:
            # Single value
            if len(field_names) != 2:
                raise ValueError(f"Field names must contain 2 entries for single value, got {len(field_names)}")
            point[field_names[1]] = val

        points.append(point)

    return {"points": points, "scale": scale}

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    * `iface` must be a class (or any type that can be passed to
      :func:`issubclass`/`isinstance`).  The function checks that
      `candidate` either is a subclass of `iface` or implements all
      attributes and methods defined on `iface`.  If *tentative* is
      ``True``, the check is lenient: non‑callable attributes missing
      from `candidate` are ignored, but missing required methods raise
      an exception.

    Raises
    ------
    TypeError
        If `iface` is not a class or `candidate` does not provide the
        required interface.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")

    # Determine whether candidate is a class or an instance
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick check for subclass or instance compatibility
    try:
        if issubclass(candidate_cls, iface):
            return
    except TypeError:
        pass

    # Verify that all attributes defined on iface exist on candidate
    missing = []
    for name in dir(iface):
        # Skip special methods unless they are defined on iface
        if name.startswith("__") and name.endswith("__"):
            if not hasattr(iface, name):
                continue
        iface_attr = getattr(iface, name, None)
        try:
            cand_attr = getattr(candidate_cls, name)
        except AttributeError:
            # For instances, try the object itself
            try:
                cand_attr = getattr(candidate, name)
            except AttributeError:
                if tentative and not callable(iface_attr):
                    continue
                missing.append(name)
                continue
        if callable(iface_attr):
            if not callable(cand_attr):
                missing.append(name)

    if missing:
        missing_str = ", ".join(missing)
        raise TypeError(f"Candidate {candidate_cls.__name__ if isinstance(candidate, type) else candidate} does not implement required members: {missing_str}")
    # If we reach here, candidate passes the verification
    return

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        val = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return val

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    # Attempt to use a frequency mapping if available
    freq = getattr(self, "_freq", None)
    try:
        if isinstance(freq, dict) and freq:
            # Find key with smallest frequency count
            least_key = min(freq, key=freq.get)
        else:
            # Fallback to an arbitrary key (first in insertion order)
            least_key = next(iter(self))
    except Exception:
        # If something goes wrong, fall back to the first key again
        least_key = next(iter(self))
    # Get the value and remove the key
    value = self[least_key]
    del self[least_key]
    # Remove from frequency map if present
    if isinstance(freq, dict) and least_key in freq:
        del freq[least_key]
    return least_key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # If the instance stores an OrderedDict (common for LRU caches),
    # prefer popping from it to preserve LRU semantics.
    if hasattr(self, "_cache"):
        cache = self._cache
        # OrderedDict has popitem with last parameter
        if hasattr(cache, "popitem") and callable(cache.popitem):
            try:
                return cache.popitem(last=False)
            except TypeError:
                # Fallback if last parameter not supported
                pass
    # Fallback to generic dict behavior: pop the first item in iteration order.
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    value = self[key]
    del self[key]
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to use the built‑in dict implementation (works for dict subclasses)
    try:
        return dict.popitem(self)
    except TypeError:
        # Fallback for custom containers that expose an OrderedDict named _data
        if hasattr(self, "_data") and hasattr(self._data, "popitem"):
            return self._data.popitem(last=True)
        # If neither works, re‑raise a clear error
        raise TypeError("popitem not supported for this object's structure") from None

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    # Attempt to instantiate the converter.  If the constructor requires
    # additional configuration this should be added here.
    try:
        return _converting._Converter()
    except Exception as exc:
        raise RuntimeError(
            "Failed to create parameter style converter"
        ) from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Private XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    if not request:
        return False
    try:
        # Check the request path – Matrix routes typically start with "/_matrix/"
        path = getattr(request, "path", None)
        if not path:
            # Some frameworks expose the path via META['PATH_INFO']
            meta = getattr(request, "META", {})
            path = meta.get("PATH_INFO")
        if path and path.startswith("/_matrix/"):
            return True

        # Check common Matrix HTTP headers
        meta = getattr(request, "META", {})
        # Authorization header usually contains a Bearer token
        auth_header = meta.get("HTTP_AUTHORIZATION")
        if auth_header and auth_header.lower().startswith("bearer "):
            return True
        # Legacy/optional custom header
        if meta.get("HTTP_X_MATRIX_PROTOCOL"):
            return True

        # Matrix requests usually send JSON
        content_type = getattr(request, "content_type", None)
        if not content_type:
            content_type = meta.get("CONTENT_TYPE")
        if content_type and content_type.startswith("application/json"):
            return True
    except Exception:
        # Any unexpected issue - treat as not a Matrix request
        pass
    return False

def process_text_links(text):
    """Process links in text, adding target="_blank" attributes to anchor tags and converting textual URLs to links."""
    url_re = re.compile(r'(https?://[^\s<]+)')
    return url_re.sub(lambda m: f'<a href="{m.group(0)}" target="_blank" rel="noopener noreferrer">{m.group(0)}</a>', text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str):
        return None
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ("http", "https"):
        return None
    req = Request(url, method="HEAD")
    try:
        with urlopen(req) as resp:
            if hasattr(resp, "status") and resp.status != 200:
                return None
            return resp.info().get("Content-Type")
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    # Tag must not be empty or whitespace only
    if not tag.strip():
        return False
    # Allowed characters: alphanumeric, hyphen and underscore only
    for char in tag:
        if not (char.isalnum() or char in "-_"):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    result = {}
    if node is None:
        return result
    for child in node:
        tag = child.tag
        # Strip XML namespaces for readability, if present
        if isinstance(tag, str) and '}' in tag:
            tag = tag.split('}', 1)[1]
        if tag in result:
            current = result[tag]
            if isinstance(current, list):
                current.append(child)
            else:
                result[tag] = [current, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, e.g. https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url or not isinstance(url, str):
        raise ValueError("A valid base URL must be provided")

    base_url = url.rstrip("/")  # remove any trailing slash for consistency

    # Determine the relative path to the NodeInfo JSON document
    if document_path:
        # Strip any leading slash to avoid double slashes
        doc_path = document_path.lstrip("/")
    else:
        # Default path used by many implementations
        doc_path = "nodeinfo.json"

    href = f"{base_url}/{doc_path}"

    # According to the NodeInfo spec, the rel and type are fixed for schema 1.0
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema#nodeinfo1.0",
                "type": "application/json",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    result: Dict[str, str] = {}

    # First attempt JSON parsing
    try:
        import json

        data = json.loads(document)
        # Extract links
        links = data.get("links", []) or []
        link_map: Dict[str, str] = {}
        for l in links:
            rel = l.get("rel", "") or ""
            href = l.get("href")
            if href:
                link_map[rel] = href
        # HCard
        for key in ("hcard", "http://webfinger.net/rel/hcard", "rel:hcard"):
            if key in link_map:
                result["hcard_url"] = link_map[key]
                break
        # LRDD
        if "lrdd" in link_map:
            result["lrdd"] = link_map["lrdd"]
        # Store additional useful fields
        if "subject" in data:
            result["subject"] = data["subject"]
        if "aliases" in data:
            result["aliases"] = data["aliases"]
        return result
    except Exception:
        # If JSON parsing fails, try XRD (XML) parsing
        try:
            import xml.etree.ElementTree as ET

            root = ET.fromstring(document)
        except Exception:
            return {}
        # Find all Link elements
        link_map: Dict[str, str] = {}
        for link in root.findall(".//{*}Link"):
            rel = link.get("rel") or ""
            href = link.get("href")
            if href:
                link_map[rel] = href
        # HCard
        for key in ("hcard", "http://webfinger.net/rel/hcard", "rel:hcard"):
            if key in link_map:
                result["hcard_url"] = link_map[key]
                break
        # LRDD
        if "lrdd" in link_map:
            result["lrdd"] = link_map["lrdd"]
        # Subject and Alias may be present
        subject_elem = root.find(".//{*}Subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text
        alias_elems = root.findall(".//{*}Alias")
        if alias_elems:
            result["aliases"] = [elem.text for elem in alias_elems if elem.text]
        return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, host = handle.split("@", 1)
    except ValueError:
        # handle does not contain a host part
        return None
    # Build the request URL for the webfinger endpoint
    try:
        import urllib.request
        import urllib.error
        url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
        try:
            with urllib.request.urlopen(url, timeout=5) as resp:
                return resp.read().decode("utf-8")
        except urllib.error.URLError:
            # Fallback to http if https fails
            url = f"http://{host}/.well-known/webfinger?resource=acct:{handle}"
            try:
                with urllib.request.urlopen(url, timeout=5) as resp:
                    return resp.read().decode("utf-8")
            except Exception:
                return None
    except Exception:
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, ValueError):
        logger.warning(
            "retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle
        )
        return None

    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)

    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        return None
    url = lrdd_link.template.replace("{uri}", quote(handle))

    document, code, exception = fetch_document(url)
    if exception:
        return None

    return parse_diaspora_webfinger(document)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Basic type checks
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dict")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    if any(not isinstance(k, str) for k in keys):
        raise TypeError("all keys must be strings")

    # No subkeys – insert at the top level
    if not keys:
        dic[key] = val
        return

    # Ensure the first key points to a dict
    if key not in dic or not isinstance(dic[key], dict):
        dic[key] = {}
    current = dic[key]

    # Iterate over intermediate subkeys (all but the last)
    for subkey in keys[:-1]:
        if subkey not in current or not isinstance(current[subkey], dict):
            current[subkey] = {}
        current = current[subkey]

    # Set the value for the last key
    current[keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""

    # Normalize input to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    # Normalize spec_option to a set of extensions
    if spec_option is None:
        extensions = None
    elif isinstance(spec_option, (str, bytes)):
        extensions = {spec_option}
    else:
        extensions = set(spec_option)

    file_names = []
    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                if extensions is None or any(fname.endswith(ext) for ext in extensions):
                    file_names.append(os.path.join(directory, fname))
        except (OSError, FileNotFoundError):
            # Skip directories that can't be accessed
            continue

    return sorted(file_names)

def ansible_config_manager(cls):
    """
    Gets the ansible config manager.
    """
    try:
        return cls._ansible_config_manager
    except AttributeError:
        try:
            from ansible.conf.manager import ConfigManager
        except ImportError as e:
            raise RuntimeError('Ansible configuration manager could not be imported') from e
        cls._ansible_config_manager = ConfigManager()
        return cls._ansible_config_manager

