@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None or not isinstance(spec_content, (str, bytes)):
            raise IRValidatorException("spec_content must be provided as a string")

        try:
            # parse yaml
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse YAML: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must represent a YAML mapping (dictionary)")

        # Define mandatory fields here
        mandatory_fields = ['spec_version', 'metadata', 'components']
        missing = [field for field in mandatory_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory field(s): {', '.join(missing)}")

        return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(
                f"Error reading YAML file {yaml_file}: {e}"
            ) from e

        if not isinstance(data, dict):
            raise IRValidatorException(
                f"YAML file {yaml_file} does not contain a mapping (found {type(data).__name__})"
            )

        required_keys = getattr(cls, "REQUIRED_KEYS", [])
        missing_keys = [key for key in required_keys if key not in data]
        if missing_keys:
            raise IRValidatorException(
                f"Missing required fields in {yaml_file}: {', '.join(missing_keys)}"
            )

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files.

        The method looks for an ``include`` key in the supplied
        ``parser_dict``.  The value can be a dictionary mapping group
        names to either another dictionary (inline include) or a file
        path pointing to a JSON/YAML file that contains a dictionary.
        Each included mapping is merged into the original ``parser_dict``
        (recursively, so nested ``include``s are also respected).  After
        processing the ``include`` key is removed. Errors encountered
        while loading a file are caught and logged via a ``logger``
        attribute if present, but do not interrupt the merge of other
        entries.
        """
        includes = parser_dict.get('include')
        if not includes:
            return parser_dict
        if not isinstance(includes, dict):
            raise TypeError("The 'include' directive must be a dictionary.")
        # Recursive merge helper
        def deep_merge(src, dst):
            for k, v in src.items():
                if k in dst and isinstance(dst[k], dict) and isinstance(v, dict):
                    deep_merge(v, dst[k])
                else:
                    dst[k] = v
        for key, inc in includes.items():
            # Resolve include value
            if isinstance(inc, str):
                # Treat as path to a JSON file
                try:
                    import json, pathlib
                    path = pathlib.Path(inc)
                    with path.open('rt', encoding='utf-8') as f:
                        inc_map = json.load(f)
                    if not isinstance(inc_map, dict):
                        raise ValueError(f"Included file {inc} does not contain a dictionary at the top level.")
                except Exception as exc:
                    if hasattr(self, 'logger'):
                        self.logger.warning(f"Failed to load include file '{inc}': {exc}")
                    continue
            elif isinstance(inc, dict):
                inc_map = inc
            else:
                # Unsupported include format; skip
                continue
            # Merge into destination
            if key in parser_dict and isinstance(parser_dict[key], dict):
                deep_merge(inc_map, parser_dict[key])
            else:
                parser_dict[key] = inc_map
        # Remove the include key after processing
        parser_dict.pop('include', None)
        return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')
        # Attempt to get a value from the spec, falling back to the option's default
        spec_val = None
        if hasattr(self, "spec"):
            try:
                spec_val = self.spec.get(arg.name, NoDefault())
            except Exception:
                spec_val = NoDefault()
        # If the spec did not provide a value, use the option's default
        if isinstance(spec_val, NoDefault):
            if isinstance(arg.default, NoDefault):
                # No default at all, skip this option
                continue
            val = arg.default
        else:
            val = spec_val
        if isinstance(arg, DictOption):
            # For dict options, build nested defaults and merge any spec overrides
            nested_defaults = {}
            if hasattr(arg.scheme, "get_spec_defaults"):
                try:
                    nested_defaults = arg.scheme.get_spec_defaults()
                except Exception:
                    nested_defaults = {}
            if isinstance(val, dict):
                nested_defaults.update(val)
            defaults[arg.name] = nested_defaults
        else:
            defaults[arg.name] = val
    return defaults

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the dictionary that holds all command specifications
    try:
        command_specs = getattr(self, "_option_spec", None)
    except Exception as exc:
        raise AttributeError("Instance is missing the `_option_spec` attribute") from exc

    if command_specs is None:
        raise AttributeError("Instance has no `_option_spec` attribute")

    # Get the spec for the particular command
    try:
        cmd_spec = command_specs.get(command_name)
    except AttributeError as exc:
        raise AttributeError("_option_spec should be a mapping") from exc

    if cmd_spec is None:
        raise ValueError(f"Command '{command_name}' not registered in option specs")

    # Get the option specification within that command
    try:
        option_spec = cmd_spec.get(argument_name)
    except AttributeError as exc:
        raise AttributeError("Command spec should be a mapping") from exc

    if option_spec is None:
        raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'")

    return option_spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Convert input to a dictionary representation
    try:
        # Namespace or any object exposing __dict__
        arg_dict = vars(args)
    except TypeError:
        # Assume args is already a dict
        arg_dict = args

    if not isinstance(arg_dict, dict):
        # Unsupported type
        return []

    silent = []
    for key, value in arg_dict.items():
        # Silenced if the value is None, empty string, boolean False,
        # or an empty collection (list/tuple/set/dict).
        if value is None:
            silent.append(key)
        elif isinstance(value, str) and value.strip() == '':
            silent.append(key)
        elif isinstance(value, bool) and not value:
            silent.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and not value:
            silent.append(key)

    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option definitions")
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument values")

    required_args = []

    for opt in options_spec:
        # skip entries that are not mappings
        if not isinstance(opt, dict):
            continue

        cond = opt.get('required_when')
        if cond is None:
            continue

        matched = False
        try:
            if callable(cond):
                matched = bool(cond(command_name, args))
            else:
                # treat as a string expression; expose 'args' and 'command_name' to eval
                matched = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False

        if matched:
            # Prefer the 'arg' key (destination name) or fall back to 'name'
            arg_name = opt.get('arg') or opt.get('name')
            if arg_name is not None:
                required_args.append(arg_name)

    return required_args

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    for name, val in args.items():
        # Determine the value and the maximum allowed length
        value = val
        max_len = None

        # If the argument value is given as a (value, max_length) tuple/list,
        # unpack it.  Otherwise look for a predefined max length that may
        # be stored on the instance either as a dedicated attribute or in
        # a mapping.
        if isinstance(val, (tuple, list)) and len(val) == 2:
            value, max_len = val
        else:
            # Check for an attribute such as `_max_len_<arg_name>`
            attr_name = f"_max_len_{name}"
            if hasattr(self, attr_name):
                max_len = getattr(self, attr_name)
            # Fall back to a generic dictionary if it exists
            elif hasattr(self, "_max_lengths") and isinstance(self._max_lengths, dict):
                max_len = self._max_lengths.get(name)

        # Skip arguments that have no length constraint
        if max_len is None:
            continue

        # Ensure the value actually supports length
        if not hasattr(value, "__len__"):
            raise TypeError(f"Argument '{name}' does not support length comparison")

        # Check the actual length against the maximum
        if len(value) > max_len:
            raise ValueError(
                f"Argument '{name}' length ({len(value)}) exceeds the maximum of {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # If the object does not expose a mapping of choices, just skip validation.
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for arg_name, value in args.items():
        if arg_name not in self.choices:
            continue

        allowed = self.choices[arg_name]
        try:
            # ``allowed`` may be a list, tuple, set or any iterable.
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of: {allowed!r}"
                )
        except TypeError:
            # ``allowed`` is not a proper collection; treat as invalid.
            raise ValueError(
                f"Cannot validate choices for argument '{arg_name}'; "
                f"invalid choices container: {allowed!r}"
            ) from None
    # If we reach this point, all choice arguments are valid. No explicit return needed.

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has the required bounds attributes.
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError(
            "Instance must have 'min_' and 'max_' attributes for validation"
        )

    min_val = self.min_
    max_val = self.max_

    # If a single value is provided instead of an iterable, treat it as a list.
    try:
        iter(args)
    except TypeError:
        args = [args]

    for val in args:
        try:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument {val!r} is out of range [{min_val}, {max_val}]"
                )
        except TypeError:
            # The comparison failed because values aren't comparable
            raise TypeError(
                f"Cannot compare argument {val!r} with bounds {min_val!r} and {max_val!r}"
            )
    return args

def create_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance or factory
    """
    # Validate inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # If a custom parsing function is provided, use it directly
    parse_func = spec_option.get("parse_func")
    if callable(parse_func):
        return parse_func

    # If a class is directly supplied in the spec, use it
    cls = spec_option.get("class")
    if isinstance(cls, type):
        return cls

    # If the spec defines fields, create a lightweight NamedTuple-like parser
    fields = spec_option.get("fields")
    if isinstance(fields, (list, tuple)):
        field_types = spec_option.get("field_types", [])
        # Ensure field_types has a type for each field, default to str
        if not isinstance(field_types, (list, tuple)):
            raise TypeError("field_types must be a list or tuple of types")
        if len(field_types) != len(fields):
            # Pad with str if not enough types specified
            field_types = list(field_types) + [str] * (len(fields) - len(field_types))

        # Create the namedtuple type
        ComplexStruct = type(type_name, (tuple,), {"__slots__": (), "__new__": type("new", (tuple,), {
            "__new__": lambda cls, *args: tuple.__new__(cls, args)
        })["__new__"]})

        # Alternative simpler approach: use collections.namedtuple
        try:
            from collections import namedtuple
            ComplexStruct = namedtuple(type_name, fields)
        except Exception as exc:
            raise RuntimeError(f"Failed to create namedtuple {type_name}: {exc}") from exc

        def parser(value):
            """
            Parse a comma-separated string into the ComplexStruct.
            """
            parts = [p.strip() for p in value.split(",")]
            if len(parts) != len(fields):
                raise ValueError(
                    f"Expected {len(fields)} values for {option_name} of type {type_name}, "
                    f"but got {len(parts)}: '{value}'"
                )
            converted = []
            for part, typ in zip(parts, field_types):
                try:
                    converted.append(typ(part))
                except Exception as exc:
                    raise ValueError(
                        f"Could not convert '{part}' to {typ.__name__} for field '{option_name}'"
                    ) from exc
            return ComplexStruct(*converted)

        parser.__name__ = f"parse_{type_name}"
        return parser

    # Fallback: If spec contains '__type__', try dynamic loading
    if "__type__" in spec_option:
        try:
            fqdn = spec_option["__type__"]
            factory = self.load_name(fqdn)  # assumes a loader method on self
            args = spec_option.get("__args__", [])
            kwargs = {k: v for k, v in spec_option.items() if k not in ("__type__", "__args__")}
            return factory(*args, **kwargs)
        except Exception as exc:
            raise RuntimeError(f"Could not construct type from spec {spec_option}: {exc}") from exc

    # If nothing matches, raise an informative error
    raise ValueError(
        f"Unable to create a complex argument type for {option_name}. "
        f"Spec must include 'parse_func', 'class', 'fields', or '__type__'."
    )

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare containers for the separated arguments
    control_args = {}
    nested_args = {}

    # Basic validation and normalisation of the input
    try:
        if args is None:
            return control_args, nested_args

        # If args is a dict, iterate over its items
        if isinstance(args, dict):
            items = args.items()

        # If args is a list of 2‑tuples, transform it to a dict
        elif isinstance(args, list):
            normalised = {}
            for entry in args:
                if isinstance(entry, (tuple, list)) and len(entry) == 2:
                    normalised[entry[0]] = entry[1]
                else:
                    raise ValueError(
                        "List entries must be two‑item key/value pairs")
            items = normalised.items()

        else:
            raise TypeError("args must be a dict or list of pairs")

        # Splitting logic
        for key, value in items:
            # Skip missing values
            if value is None:
                continue

            # Determine if the argument is a control argument.
            # A very simple heuristic: keys starting with '_' or 'control_'
            # are treated as control arguments. Extend this logic if the
            # calling code defines a more explicit list.
            is_control = (
                isinstance(key, str) and (
                    key.startswith('_')
                    or key.lower().startswith('control_')
                )
            )

            if is_control:
                control_args[key] = value
            else:
                # All other keys are treated as nested or custom arguments
                nested_args[key] = value

        return control_args, nested_args

    except Exception as exc:
        # In the unlikely event of an error, return empty dicts to avoid
        # catastrophic failure in the caller. The caller can decide if the
        # error should be surfaced.
        return {}, {}

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :returns: Dictionary extended with extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    result = dict(vars_dict)

    if extra_vars is None:
        return result

    # Handle a single dictionary
    if isinstance(extra_vars, dict):
        result.update(extra_vars)
        return result

    # Handle a list of items
    if isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                result.update(item)
            elif isinstance(item, str):
                if '=' in item:
                    key, val = item.split('=', 1)
                    result[key] = val
            else:
                # unsupported item type, ignore or raise
                raise ValueError(f"Unsupported extra var type: {type(item)}")
        return result

    # Handle a string like "key=value"
    if isinstance(extra_vars, str):
        if '=' in extra_vars:
            key, val = extra_vars.split('=', 1)
            result[key] = val
        else:
            raise ValueError("String extra vars must be in 'key=value' format")
        return result

    # Unsupported type for extra_vars
    raise ValueError(f"Unsupported type for extra_vars: {type(extra_vars)}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Known type mappings for each parser. Extend this map as needed.
    known_type_map = {
        'main': {
            'port': int,
            'verbose': bool,
            'debug': bool,
            'timeout': int
        },
        'virsh': {
            'timeout': int,
            'force': bool
        },
        'ospd': {
            'threads': int,
            'enable': bool
        }
    }

    parser_map = known_type_map.get(parser_name, {})

    for key, value in values_dict.items():
        # Skip None values – leave as is
        if value is None:
            continue

        # If parser provides explicit type, use it
        if key in parser_map:
            try:
                values_dict[key] = parser_map[key](value)
                continue
            except Exception:
                # If conversion fails, fall back to generic rules below
                pass

        # Generic conversion for strings
        if isinstance(value, str):
            lowered = value.lower()

            # Boolean values
            if lowered in ('true', 'false'):
                values_dict[key] = lowered == 'true'
                continue

            # Try integer conversion
            try:
                values_dict[key] = int(value)
                continue
            except ValueError:
                pass

            # Try float conversion
            try:
                values_dict[key] = float(value)
                continue
            except ValueError:
                pass

        # Fall back: keep original value (likely already correct type)
        # (no modification)

    # The dict is modified in place; returning it is optional but convenient.
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key="", sep="_"):
        flattened = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flattened.update(_flatten(value, new_key, sep=sep))
            elif isinstance(value, list):
                # Convert lists to comma‑separated strings for flattening
                flattened[new_key] = json.dumps(value)
            else:
                flattened[new_key] = value
        return flattened

    # Common filenames where a plugin might store its metadata
    possible_files = ("plugin.json", "metadata.json", "manifest.json")
    spec_path = None
    for fname in possible_files:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        raise FileNotFoundError(
            f"No plugin spec file found in '{plugin_dir}'. "
            f"Tried: {', '.join(possible_files)}"
        )

    try:
        with open(spec_path, "r", encoding="utf-8") as fh:
            spec = json.load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to read or parse plugin spec from '{spec_path}': {exc}")

    if not isinstance(spec, dict):
        raise ValueError(f"The plugin spec at '{spec_path}' is not a JSON object (dict).")

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    # Determine the config path to use
    if not hasattr(self, 'config_path'):
        logger.error("inject_config: 'config_path' attribute not found on %s", self)
        raise AttributeError("Missing 'config_path' attribute on object")
    try:
        config_path = str(self.config_path)
    except Exception as exc:
        logger.exception("Failed to convert config_path to string: %s", exc)
        raise

    # Name of the environment variable to set
    env_var = 'CONFIG_PATH'

    # If the variable is not already defined, set it
    if env_var not in os.environ:
        try:
            os.environ[env_var] = config_path
            logger.debug("Set environment variable '%s' to '%s'", env_var, config_path)
        except Exception as exc:
            logger.exception("Could not set environment variable '%s': %s", env_var, exc)
            raise
    else:
        logger.debug("Environment variable '%s' is already set to '%s'", env_var, os.environ[env_var])
    return None

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        import os
        path_abs = os.path.abspath(path)
        root_abs = os.path.abspath(root)
        if not path_abs.startswith(root_abs):
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
        rel = path_abs[len(root_abs):]
        if rel.startswith(os.sep):
            rel = rel[1:]
        if rel == '':
            rel = '.'
        return rel
    except Exception as e:
        raise e
